<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {fetchOperations,createOperation,advanceBatch,fetchBatchTrace,type OperationRecord} from '@/api/dashboard'
import {useWorkspaceStore} from '@/stores/workspace'
const props=defineProps<{kind:'crops'|'devices'|'irrigation'|'alerts';entityId?:string}>()
const store=useWorkspaceStore(),rows=ref<OperationRecord[]>([]),trace=ref<OperationRecord[]>([]),traceId=ref<number|null>(null),error=ref(''),busy=ref(false),loading=ref(false),editor=ref(false)
const recordKind=ref('AGRONOMY'),title=ref(''),detail=ref(''),quantity=ref(100),unit=ref('kg'),plotId=ref(''),filter=ref('all'),query=ref(''),stageNote=ref('')
const labels:Record<string,string>={AGRONOMY:'农事记录',GROWTH:'生长记录',BATCH:'采后批次',BATCH_EVENT:'批次流转',DEVICE_RECEIPT:'设施回执',IRRIGATION_RECEIPT:'灌排回执',ALERT_RECEIPT:'告警处置'}
const stages:Record<string,string>={RECORDED:'已登记',COMPLETED:'已完成',HARVESTED:'已采收',SORTED:'已分选',STORED:'已入库',DISPATCHED:'已出库'}
const next:Record<string,string>={HARVESTED:'SORTED',SORTED:'STORED',STORED:'DISPATCHED'}
const farmId=computed(()=>store.snapshot?.farmId||'yantian-01')
const plots=computed(()=>store.snapshot?.zones||[])
const visible=computed(()=>rows.value.filter(r=>props.kind==='crops'?['AGRONOMY','GROWTH','BATCH'].includes(r.kind):r.kind===({devices:'DEVICE_RECEIPT',irrigation:'IRRIGATION_RECEIPT',alerts:'ALERT_RECEIPT'} as Record<string,string>)[props.kind]).filter(r=>filter.value==='all'||r.entityId===filter.value).filter(r=>`${r.title} ${r.detail} ${r.id}`.includes(query.value.trim())))
let generation=0
async function load(){const version=++generation;loading.value=true;error.value='';try{const result=await fetchOperations(farmId.value);if(version===generation)rows.value=result}catch(e){if(version===generation)error.value=e instanceof Error?e.message:'读取失败'}finally{if(version===generation)loading.value=false}}
watch(farmId,()=>{rows.value=[];trace.value=[];traceId.value=null;filter.value='all';editor.value=false;load()},{immediate:true})
watch(()=>store.snapshot?.generatedAt,()=>load())
watch(()=>props.entityId,id=>{if(plots.value.some(p=>p.entityId===id))plotId.value=id||''},{immediate:true})
function openEditor(){plotId.value=plots.value.some(p=>p.entityId===props.entityId)?props.entityId||'':plots.value[0]?.entityId||'';editor.value=true}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await createOperation({kind:recordKind.value,entityId:plotId.value,title:title.value.trim(),detail:detail.value.trim(),...(recordKind.value==='BATCH'?{quantity:quantity.value,unit:unit.value}:{})},farmId.value);editor.value=false;title.value='';detail.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function viewTrace(row:OperationRecord){traceId.value=row.id;stageNote.value='';trace.value=[];try{trace.value=await fetchBatchTrace(row.id,farmId.value)}catch(e){error.value=e instanceof Error?e.message:'追溯读取失败'}}
async function advance(row:OperationRecord){if(busy.value||!stageNote.value.trim())return;busy.value=true;error.value='';try{const updated=await advanceBatch(row.id,next[row.stage],stageNote.value.trim(),farmId.value);await load();await viewTrace(updated)}catch(e){error.value=e instanceof Error?e.message:'流转失败'}finally{busy.value=false}}
function download(){const data={schemaVersion:1,farmId:farmId.value,simulated:true,exportedAt:new Date().toISOString(),records:visible.value,trace:trace.value};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='盐田丰语-业务记录.json';link.click();URL.revokeObjectURL(url)}
</script>
<template>
<section class="operation-journal" aria-label="业务记录与追溯">
 <header><h3>{{ kind==='crops'?'农事与采后追溯':'执行与处置记录' }}</h3><button :disabled="loading||busy" @click="load">{{ loading?'读取中…':'刷新记录' }}</button></header>
 <p>共享软件演示记录 · 最近 200 条业务事件，不代表实际生产操作。</p>
 <div class="journal-tools"><select v-model="filter" aria-label="业务记录地块筛选"><option value="all">全部对象</option><option v-for="p in plots" :key="p.entityId" :value="p.entityId">{{ store.snapshot?.entities.find(e=>e.id===p.entityId)?.name||p.entityId }}</option></select><button v-if="kind==='crops'" @click="openEditor">登记记录</button><button :disabled="!visible.length" @click="download">导出</button></div>
 <input v-model="query" class="journal-search" aria-label="搜索业务记录" placeholder="搜索标题、说明或批次编号"><p v-if="error" class="journal-error" role="alert">{{ error }}</p>
 <form v-if="editor" @submit.prevent="save"><label>记录类型<select v-model="recordKind"><option value="AGRONOMY">农事记录</option><option value="GROWTH">生长记录</option><option value="BATCH">采后批次</option></select></label><label>所属地块<select v-model="plotId" required><option value="" disabled>选择地块</option><option v-for="p in plots" :key="p.entityId" :value="p.entityId">{{ store.snapshot?.entities.find(e=>e.id===p.entityId)?.name||p.entityId }}</option></select></label><label>标题<input v-model="title" required maxlength="160" placeholder="例如：鸭梨秋季采收批次"></label><label>记录内容<textarea v-model="detail" required maxlength="2000" rows="3" placeholder="填写模拟操作、生长观察或批次说明"></textarea></label><div v-if="recordKind==='BATCH'" class="quantity-fields"><label>数量<input v-model.number="quantity" type="number" required min="0.01" step="0.01"></label><label>单位<input v-model="unit" required maxlength="20"></label></div><div class="journal-actions"><button type="button" :disabled="busy" @click="editor=false">取消</button><button class="primary" :disabled="busy">{{ busy?'保存中…':'保存记录' }}</button></div></form>
 <p v-if="!visible.length&&!loading" class="empty">还没有记录。{{ kind==='crops'?'登记农事、生长观察或采收批次后显示。':'完成模拟操作后自动保存回执。' }}</p>
 <article v-for="row in visible" :key="row.id"><div class="record-head"><small>{{ labels[row.kind] }}</small><span>{{ stages[row.stage]||row.stage }}</span></div><strong>{{ row.title }}</strong><p>{{ row.detail }}</p><small>{{ new Date(row.createdAt).toLocaleString('zh-CN',{hour12:false}) }} · {{ row.operatorName||'演示系统' }} · {{ row.entityId }}<template v-if="row.quantity"> · {{ row.quantity }} {{ row.unit }}</template></small><button v-if="row.kind==='BATCH'" class="trace-link" @click="viewTrace(row)">批次 #{{ row.id }} · 查看追溯</button><div v-if="traceId===row.id" class="batch-trace"><ol><li v-for="event in trace" :key="event.id"><b>{{ stages[event.stage] }}</b><time>{{ new Date(event.createdAt).toLocaleString('zh-CN',{hour12:false}) }}</time><p>{{ event.detail }}</p></li></ol><template v-if="next[row.stage]"><label>本次{{ stages[next[row.stage]] }}说明<textarea v-model="stageNote" required maxlength="2000" rows="2" placeholder="分选等级、库位或出库去向"></textarea></label><button class="primary" :disabled="busy||!stageNote.trim()" @click="advance(row)">确认{{ stages[next[row.stage]] }}</button></template><p v-else>批次流程已完成，全部流转记录保留。</p></div></article>
</section>
</template>
<style scoped>
.operation-journal{color:var(--ui-ink)}header,.record-head,.journal-tools,.journal-actions{display:flex;align-items:center;justify-content:space-between;gap:8px}h3{font-size:12px;margin:0}p{font-size:10px;color:var(--ui-muted);line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}button{font:inherit;font-size:10px;border:1px solid var(--ui-border);border-radius:8px;padding:7px 9px;background:var(--ui-subtle);color:var(--ui-brand);cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:var(--ui-brand);color:white;border-color:var(--ui-brand)}select,input,textarea{box-sizing:border-box;width:100%;min-width:0;font:inherit;font-size:11px;border:1px solid var(--ui-border);border-radius:8px;padding:8px;background:var(--ui-subtle);color:var(--ui-ink)}.journal-search{margin-top:10px}.journal-tools select{flex:1;width:0}.journal-tools button{flex:none}form,.batch-trace{margin-top:12px;padding:12px;background:var(--ui-subtle);border-radius:10px}label{display:flex;flex-direction:column;gap:6px;font-size:10px;color:var(--ui-secondary);margin-bottom:10px}.quantity-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.journal-actions{justify-content:flex-end}.journal-error{color:var(--ui-danger)}article{padding:14px 0;border-bottom:1px solid var(--ui-border)}article:last-child{border:0}article>strong{display:block;font-size:12px;margin-top:7px}small,time{font-size:10px;color:var(--ui-muted)}.record-head span{font-size:10px;color:var(--ui-brand)}.trace-link{display:block;margin-top:10px}ol{padding-left:16px;margin:0}li{padding:0 0 12px;font-size:11px}time{display:block;margin-top:4px}.empty{padding:16px 0;text-align:center}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid var(--ui-brand);outline-offset:2px}
</style>
